import type { CompactWord } from "./vocab-generator";

// ============================================================
// Helper: compact B1 word (no examples needed, generator adds them)
// ============================================================

function bw(word: string, ipa: string, zh: string, pos: string, dif: string = "m"): CompactWord {
  return { w: word, ipa, zh, pos, dif, ex: "", exzh: "" };
}

